-- Table partitionnee par plage de dates : une partition par trimestre.
CREATE TABLE evenements (
  id          uuid DEFAULT uuidv7(),
  survenu_le  timestamptz NOT NULL,
  donnees     jsonb
) PARTITION BY RANGE (survenu_le);

-- Chaque partition ne contient que les lignes de son intervalle.
CREATE TABLE evenements_2026_t1 PARTITION OF evenements
  FOR VALUES FROM ('2026-01-01') TO ('2026-04-01');

CREATE TABLE evenements_2026_t2 PARTITION OF evenements
  FOR VALUES FROM ('2026-04-01') TO ('2026-07-01');

-- Une requete filtrant sur survenu_le ne lit que la ou les partitions utiles,
-- au lieu de parcourir toute la table : c'est l'elagage de partitions.
